import numpy as np
import scipy.ndimage
import numba


@numba.njit(cache=True, parallel=True, fastmath=False)
def _interp(coeff, out, m00, m01, m02, m10, m11, m12):
    n = coeff.shape[0]
    nm1 = n - 1
    for y in numba.prange(n):
        for x in range(n):
            iy = m00 * y + m01 * x + m02
            ix = m10 * y + m11 * x + m12
            if iy < 0.0 or iy > nm1 or ix < 0.0 or ix > nm1:
                out[y, x] = 0.0
                continue
            fy = int(iy)
            fx = int(ix)
            ty = iy - fy
            tx = ix - fx
            wy0 = (1.0 - ty) ** 3 / 6.0
            wy1 = 2.0 / 3.0 - ty * ty + ty * ty * ty / 2.0
            wy2 = 2.0 / 3.0 - (1.0 - ty) ** 2 + (1.0 - ty) ** 3 / 2.0
            wy3 = ty ** 3 / 6.0
            wx0 = (1.0 - tx) ** 3 / 6.0
            wx1 = 2.0 / 3.0 - tx * tx + tx * tx * tx / 2.0
            wx2 = 2.0 / 3.0 - (1.0 - tx) ** 2 + (1.0 - tx) ** 3 / 2.0
            wx3 = tx ** 3 / 6.0
            acc = 0.0
            for j in range(4):
                yy = fy - 1 + j
                if yy < 0:
                    yy = -yy
                elif yy >= n:
                    yy = 2 * n - 2 - yy
                if j == 0:
                    wy = wy0
                elif j == 1:
                    wy = wy1
                elif j == 2:
                    wy = wy2
                else:
                    wy = wy3
                row = coeff[yy]
                s = 0.0
                for i in range(4):
                    xx = fx - 1 + i
                    if xx < 0:
                        xx = -xx
                    elif xx >= n:
                        xx = 2 * n - 2 - xx
                    if i == 0:
                        wx = wx0
                    elif i == 1:
                        wx = wx1
                    elif i == 2:
                        wx = wx2
                    else:
                        wx = wx3
                    s += row[xx] * wx
                acc += wy * s
            out[y, x] = acc


class Solver:
    def solve(self, problem, **kwargs):
        image = np.asarray(problem["image"], dtype=np.float64)
        matrix = np.asarray(problem["matrix"], dtype=np.float64)
        coeff = scipy.ndimage.spline_filter(image, order=3, mode="constant")
        out = np.empty_like(image)
        _interp(
            coeff, out,
            matrix[0, 0], matrix[0, 1], matrix[0, 2],
            matrix[1, 0], matrix[1, 1], matrix[1, 2],
        )
        return {"transformed_image": out}

