    uint64_t x = 1;
    for (uint64_t i = 0; i < m; i++) {
        uint64_t idx = (x * 0x9E3779B97F4A7C15ULL) >> shift;
        while (keys[idx] != 0) idx = (idx + 1) & mask;
        keys[idx] = x;
        vals[idx] = i;
        x = mulmod(x, g, p);
